import React, { useContext, useState } from 'react';

import AppLayout from '~components/app-layout';
import BreadcrumbGroup from '~components/breadcrumb-group';
import SpaceBetween from '~components/space-between';

import AppContext, { AppContextType } from '../app/app-context';
import labels from './utils/labels';

type DemoContext = React.Context<
  AppContextType<{
    hasOwnBreadcrumbs: boolean | undefined;
  }>
>;

export default function () {
  const { urlParams, setUrlParams } = useContext(AppContext as DemoContext);
  const [extraBreadcrumb, setExtraBreadcrumb] = useState(false);

  return (
    <AppLayout
      ariaLabels={labels}
      breadcrumbs={
        urlParams.hasOwnBreadcrumbs && (
          <BreadcrumbGroup
            items={[
              { text: 'Own', href: '#' },
              { text: 'instance', href: '#' },
            ]}
          />
        )
      }
      content={
        <SpaceBetween size="m">
          <h1>Page with additional breadcrumbs</h1>
          <BreadcrumbGroup
            items={[
              { text: 'Default', href: '#' },
              { text: 'one', href: '#' },
            ]}
          />
          <label>
            <input
              type="checkbox"
              data-testid="toggle-extra-breadcrumb"
              checked={extraBreadcrumb}
              onChange={event => setExtraBreadcrumb(event.target.checked)}
            />{' '}
            Extra breadcrumb
          </label>
          <label>
            <input
              type="checkbox"
              data-testid="toggle-own-breadcrumb"
              checked={urlParams.hasOwnBreadcrumbs || false}
              onChange={event => setUrlParams({ hasOwnBreadcrumbs: event.target.checked || undefined })}
            />{' '}
            Own breadcrumb
          </label>
          {extraBreadcrumb && (
            <BreadcrumbGroup
              items={[
                { text: 'Dynamic', href: '#' },
                { text: 'instance', href: '#' },
              ]}
            />
          )}
        </SpaceBetween>
      }
    />
  );
}

